<?php
/** Operations module: order, customer and delivery data for the existing app. */

function op_admin(): void
{
    require_login();
    if (($_SESSION['role'] ?? 'admin') !== 'admin') {
        http_response_code(403);
        exit('Administrator access required.');
    }
}

function op_owner(): int
{
    return ($_SESSION['role'] ?? 'admin') === 'rider'
        ? (int)($_SESSION['owner_id'] ?? 0)
        : user_id();
}

function op_status_label(string $status): string
{
    return ucwords(str_replace('_', ' ', $status));
}

function op_period_status_counts(PDO $pdo,string $table,string $dateColumn,int $owner):array
{
    if(!in_array($table,['orders','deliveries'],true)||!in_array($dateColumn,['ordered_at','created_at'],true))throw new InvalidArgumentException('Unsupported metrics query.');
    $from=date('Y-m-01');$previous=date('Y-m-01',strtotime('-1 month'));$sql="SELECT status,COUNT(*) amount FROM $table WHERE owner_id=? AND $dateColumn>=? AND $dateColumn<? GROUP BY status";$counts=[];$s=$pdo->prepare($sql);$s->execute([$owner,$from,date('Y-m-01',strtotime('+1 month'))]);foreach($s as $r)$counts[$r['status']]=(int)$r['amount'];$old=[];$s=$pdo->prepare($sql);$s->execute([$owner,$previous,$from]);foreach($s as $r)$old[$r['status']]=(int)$r['amount'];return [$counts,$old];
}

function op_delivery_performance(PDO $pdo,int $owner):array
{
    $s=$pdo->prepare("SELECT AVG(CASE WHEN started_at IS NOT NULL AND delivered_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,started_at,delivered_at) END) avg_minutes,SUM(status='delivered' AND eta_at IS NOT NULL AND delivered_at<=eta_at) on_time,SUM(status='delivered') delivered,SUM(status='failed') failed,SUM(status='exception') exceptions,AVG(route_distance_km) avg_distance FROM deliveries WHERE owner_id=?");$s->execute([$owner]);return $s->fetch()?:[];
}

function op_change_label(int|float $current,int|float $previous):string
{
    if($previous<=0)return $current>0?'New this month':'0%';$value=(($current-$previous)/$previous)*100;return ($value>0?'+':($value<0?'−':'' )).number_format(abs($value),1).'%';
}

function op_period_change(array $current,array $previous,string $key='all'):string
{
    $sum=static function(array $data,string $name):int { if($name==='all')return array_sum($data);if($name==='active')return array_sum(array_intersect_key($data,array_flip(['accepted','preparing','ready_for_pickup','picked_up','out_for_delivery'])));return (int)($data[$name]??0); };
    return op_change_label($sum($current,$key),$sum($previous,$key));
}

function op_customer_growth(PDO $pdo,int $owner):string
{
    $month=date('Y-m-01');$previous=date('Y-m-01',strtotime('-1 month'));$s=$pdo->prepare('SELECT SUM(created_at>=?) current_count,SUM(created_at>=? AND created_at<?) previous_count FROM customers WHERE owner_id=?');$s->execute([$month,$previous,$month,$owner]);$r=$s->fetch();return op_change_label((int)$r['current_count'],(int)$r['previous_count']);
}

function op_redirect_order(int $id): never { header('Location: ?page=order_view&id='.(int)$id); exit; }
function op_redirect_delivery(string $role,int $id): never { if($role==='rider'){redirect('rider_dashboard');} header('Location: ?page=delivery_view&id='.(int)$id); exit; }

function op_record_event(PDO $pdo, int $deliveryId, string $status, string $note=''): void
{
    $s=$pdo->prepare('INSERT INTO delivery_events(delivery_id,actor_user_id,status,note) VALUES(?,?,?,?)');
    $s->execute([$deliveryId,user_id() ?: null,$status,$note ?: null]);
}

/** Applies operational form actions. Main auth and inventory actions remain in index.php. */
function operations_handle_post(PDO $pdo, string $action): bool
{
    $adminActions=['customer_save','customer_toggle','order_create','order_status','rider_create','rider_availability','delivery_assign','delivery_status','exception_resolve'];
    $riderActions=['rider_delivery_status','gps_update','exception_report'];
    if (!in_array($action,array_merge($adminActions,$riderActions),true)) return false;
    require_login();
    $role=$_SESSION['role'] ?? 'admin';
    if (in_array($action,$adminActions,true) && $role!=='admin') { http_response_code(403); exit('Administrator access required.'); }
    if (in_array($action,$riderActions,true) && $role!=='rider') { http_response_code(403); exit('Rider access required.'); }
    $owner=op_owner();

    if ($action==='customer_save') {
        $name=field('full_name',160); $email=strtolower(field('email',190)); $phone=field('phone',40); $address=field('address',500);
        if ($name==='' || ($email!=='' && !filter_var($email,FILTER_VALIDATE_EMAIL))) { flash('Enter a customer name and a valid email address.'); redirect('customers'); }
        $pdo->beginTransaction();
        try { $s=$pdo->prepare('INSERT INTO customers(owner_id,full_name,email,phone) VALUES(?,?,?,?)'); $s->execute([$owner,$name,$email?:null,$phone?:null]); $cid=(int)$pdo->lastInsertId(); if($address!=='')$pdo->prepare('INSERT INTO customer_addresses(customer_id,label,address_text,is_default) VALUES(?,?,?,1)')->execute([$cid,field('address_label',80)?:'Home',$address]); $pdo->commit(); flash('Customer added.'); }
        catch(Throwable $e){$pdo->rollBack();error_log('Customer save failed: '.$e->getMessage());flash('Could not save the customer. Check that the email is not already in use for this store.');}
        redirect('customers');
    }
    if ($action==='customer_toggle') { $pdo->prepare("UPDATE customers SET status=IF(status='active','inactive','active') WHERE id=? AND owner_id=?")->execute([(int)($_POST['id']??0),$owner]); flash('Customer status updated.'); redirect('customers'); }

    if ($action==='order_create') {
        $customer=(int)($_POST['customer_id']??0); $fee=max(0,(float)($_POST['delivery_fee']??0)); $discount=max(0,(float)($_POST['discount']??0));
        $c=$pdo->prepare('SELECT id FROM customers WHERE id=? AND owner_id=? AND status=\'active\'');$c->execute([$customer,$owner]); if(!$c->fetchColumn()){flash('Choose an active customer from this account.');redirect('orders');}
        $productIds=is_array($_POST['product_id']??null)?$_POST['product_id']:[($_POST['product_id']??0)];$quantities=is_array($_POST['quantity']??null)?$_POST['quantity']:[($_POST['quantity']??1)];$prices=is_array($_POST['unit_price']??null)?$_POST['unit_price']:[($_POST['unit_price']??0)];$lines=[];$subtotal=0.0;$p=$pdo->prepare('SELECT id,name,unit_cost,quantity FROM products WHERE id=? AND user_id=?');
        foreach($productIds as $i=>$pid){$pid=(int)$pid;$qty=(float)($quantities[$i]??0);if($pid<1||$qty<=0){flash('Add at least one product and a positive quantity.');redirect('orders');}$p->execute([$pid,$owner]);$prod=$p->fetch();if(!$prod){flash('One selected product does not belong to this inventory.');redirect('orders');}$price=max(0,(float)($prices[$i]??$prod['unit_cost']));$lineTotal=round($qty*$price,2);$subtotal+=$lineTotal;$lines[]=['product'=>$prod,'quantity'=>$qty,'price'=>$price,'line_total'=>$lineTotal];}
        $subtotal=round($subtotal,2);$total=max(0,round($subtotal+$fee-$discount,2));
        $address=field('delivery_address',500);$destinationLat=trim((string)($_POST['destination_latitude']??''));$destinationLon=trim((string)($_POST['destination_longitude']??''));
        $lat=($destinationLat!=='' && is_numeric($destinationLat) && abs((float)$destinationLat)<=90)?(float)$destinationLat:null;$lon=($destinationLon!=='' && is_numeric($destinationLon) && abs((float)$destinationLon)<=180)?(float)$destinationLon:null;
        $orderNo='FS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$trackToken=bin2hex(random_bytes(24));$proofCode=(string)random_int(100000,999999);$deliveryId=0;
        $pdo->beginTransaction();
        try {
            foreach($lines as $line){$reserve=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=? AND user_id=? AND quantity>=?');$reserve->execute([$line['quantity'],$line['product']['id'],$owner,$line['quantity']]);if($reserve->rowCount()!==1)throw new DomainException('INSUFFICIENT_STOCK');}
            $s=$pdo->prepare('INSERT INTO orders(owner_id,customer_id,order_number,source,status,payment_status,payment_method,subtotal,delivery_fee,discount,total_amount,delivery_address,departure_location,stock_reserved) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1)');
            $s->execute([$owner,$customer,$orderNo,in_array($_POST['source']??'', ['website','mobile','in_store'],true)?$_POST['source']:'in_store','pending',in_array($_POST['payment_status']??'', ['pending','paid','failed','refunded'],true)?$_POST['payment_status']:'pending',field('payment_method',60)?:null,$subtotal,$fee,$discount,$total,$address?:null,field('departure_location',250)?:null]);$orderId=(int)$pdo->lastInsertId();
            $payStatus=in_array($_POST['payment_status']??'', ['pending','paid','failed','refunded'],true)?$_POST['payment_status']:'pending';
            $pdo->prepare('INSERT INTO payments(order_id,amount,method,status,paid_at) VALUES(?,?,?,?,IF(?=\'paid\',NOW(),NULL))')->execute([$orderId,$total,field('payment_method',60)?:null,$payStatus,$payStatus]);
            foreach($lines as $line)$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)')->execute([$orderId,$line['product']['id'],$line['product']['name'],$line['quantity'],$line['price'],$line['line_total']]);
            $s=$pdo->prepare('INSERT INTO deliveries(owner_id,order_id,tracking_code,tracking_token_hash,status,destination_latitude,destination_longitude,proof_code_hash) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$owner,$orderId,'TRK-'.strtoupper(bin2hex(random_bytes(4))),hash('sha256',$trackToken),'assigned',$lat,$lon,password_hash($proofCode,PASSWORD_DEFAULT)]);$deliveryId=(int)$pdo->lastInsertId();
            op_record_event($pdo,$deliveryId,'order_confirmed','Order recorded');op_record_event($pdo,$deliveryId,'assigned','Delivery created; rider assignment pending');$pdo->commit();
            flash('Order '.$orderNo.' created. Customer tracking link: '.('http://'.($_SERVER['HTTP_HOST']??'localhost').APP_URL.'/?track='.$trackToken).' | Share proof code '.$proofCode.' securely with the customer.');
        } catch(Throwable $e){$pdo->rollBack();if($e instanceof DomainException && $e->getMessage()==='INSUFFICIENT_STOCK')flash('A selected product no longer has enough stock. Review quantities and try again.');else{error_log('Order create failed: '.$e->getMessage());flash('Could not create the order. Check the customer, product and database migration.');}}
        redirect('orders');
    }

    if ($action==='order_status') {
        $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['pending','processing','completed','cancelled'],true)){flash('Invalid order status.');redirect('orders');}
        $pdo->beginTransaction();try{$s=$pdo->prepare('SELECT stock_reserved,stock_restored_at,status FROM orders WHERE id=? AND owner_id=? FOR UPDATE');$s->execute([$id,$owner]);$old=$s->fetch();if(!$old){$pdo->rollBack();flash('Order not found.');redirect('orders');}if($status==='cancelled'&&$old['status']==='completed')throw new DomainException('COMPLETED_ORDER');if($status==='completed'){$s=$pdo->prepare("SELECT status FROM deliveries WHERE order_id=? AND owner_id=?");$s->execute([$id,$owner]);if($s->fetchColumn()!=='delivered')throw new DomainException('DELIVERY_NOT_DONE');}if($status==='cancelled'&&(int)$old['stock_reserved']===1&&$old['stock_restored_at']===null){$items=rows($pdo,'SELECT product_id,quantity FROM order_items WHERE order_id=?',[$id]);foreach($items as $item)if($item['product_id']!==null)$pdo->prepare('UPDATE products SET quantity=quantity+? WHERE id=? AND user_id=?')->execute([$item['quantity'],$item['product_id'],$owner]);$pdo->prepare('UPDATE orders SET stock_restored_at=NOW() WHERE id=?')->execute([$id]);}$pdo->prepare('UPDATE orders SET status=? WHERE id=? AND owner_id=?')->execute([$status,$id,$owner]);if($status==='cancelled')$pdo->prepare("UPDATE deliveries SET status='cancelled' WHERE order_id=? AND owner_id=? AND status NOT IN ('delivered','returned')")->execute([$id,$owner]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof DomainException && $e->getMessage()==='COMPLETED_ORDER')flash('A completed order cannot be cancelled.');elseif($e instanceof DomainException && $e->getMessage()==='DELIVERY_NOT_DONE')flash('Complete delivery with the customer proof code before completing the order.');else{error_log('Order status update failed: '.$e->getMessage());flash('Could not update the order.');}op_redirect_order($id);}
        flash('Order status updated.');op_redirect_order($id);
    }

    if ($action==='rider_create') {
        $name=field('name',120);$email=strtolower(field('email',190));$phone=field('phone',40);$vehicle=field('vehicle',100);$password=(string)($_POST['password']??'');
        if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('Enter rider name, valid email and a password of at least 8 characters.');redirect('deliveries');}
        $pdo->beginTransaction();try{$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,owner_id) VALUES(?,?,?,'rider',?)");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$owner]);$riderUser=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO delivery_riders(owner_id,user_id,phone,vehicle) VALUES(?,?,?,?)')->execute([$owner,$riderUser,$phone?:null,$vehicle?:null]);$pdo->commit();flash('Rider account created. Share the sign-in URL and credentials directly with the rider.');}catch(Throwable $e){$pdo->rollBack();error_log('Rider creation failed: '.$e->getMessage());flash('Could not create rider. The email may already belong to an account.');}redirect('deliveries');
    }
    if ($action==='rider_availability') { $pdo->prepare("UPDATE delivery_riders SET availability=IF(availability='available','unavailable','available') WHERE id=? AND owner_id=?")->execute([(int)$_POST['id'],$owner]);flash('Rider availability updated.');redirect('deliveries'); }
    if ($action==='delivery_assign') {
        $delivery=(int)($_POST['delivery_id']??0);$rider=(int)($_POST['rider_id']??0);$override=isset($_POST['override_unavailable']);
        $s=$pdo->prepare('SELECT id,availability FROM delivery_riders WHERE id=? AND owner_id=?');$s->execute([$rider,$owner]);$r=$s->fetch();if(!$r||($r['availability']!=='available'&&!$override)){flash('Choose an available rider or check the administrator override.');redirect('deliveries');}
        $s=$pdo->prepare("UPDATE deliveries SET rider_id=?,status=IF(status='assigned','assigned',status) WHERE id=? AND owner_id=? AND status NOT IN ('delivered','cancelled','returned')");$s->execute([$rider,$delivery,$owner]);if($s->rowCount())op_record_event($pdo,$delivery,'rider_assigned','Rider assigned / reassigned');flash('Rider assignment saved.');redirect('deliveries');
    }
    if ($action==='delivery_status' || $action==='rider_delivery_status') {
        $delivery=(int)($_POST['delivery_id']??0);$status=(string)($_POST['status']??'');$allowed=['accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','returned','failed'];if(!in_array($status,$allowed,true)){flash('Invalid delivery status.');redirect($role==='rider'?'rider_dashboard':'deliveries');}
        if($role==='rider'){$s=$pdo->prepare('SELECT d.id,d.status,d.proof_code_hash FROM deliveries d JOIN delivery_riders r ON r.id=d.rider_id WHERE d.id=? AND r.user_id=? AND d.owner_id=?');$s->execute([$delivery,user_id(),$owner]);}else{$s=$pdo->prepare('SELECT id,status,proof_code_hash FROM deliveries WHERE id=? AND owner_id=?');$s->execute([$delivery,$owner]);}$d=$s->fetch();if(!$d){http_response_code(404);exit('Delivery not found or not assigned to this account.');}
        if($role==='rider'){$next=['assigned'=>['accepted'],'accepted'=>['preparing'],'preparing'=>['ready_for_pickup'],'ready_for_pickup'=>['picked_up'],'picked_up'=>['out_for_delivery'],'out_for_delivery'=>['delivered']];if(!in_array($status,$next[$d['status']]??[],true)){flash('Update delivery stages in order. The requested stage is not available yet.');op_redirect_delivery($role,$delivery);}}
        if($status==='delivered'){$code=field('proof_code',6);if(!password_verify($code,$d['proof_code_hash'])){flash('The customer proof code is incorrect. Delivery was not marked delivered.');op_redirect_delivery($role,$delivery);}$pdo->prepare('UPDATE deliveries SET proof_verified_at=NOW(),delivered_at=NOW() WHERE id=?')->execute([$delivery]);}
        $pdo->prepare('UPDATE deliveries SET status=?,started_at=IF(?=\'out_for_delivery\' AND started_at IS NULL,NOW(),started_at) WHERE id=?')->execute([$status,$status,$delivery]);op_record_event($pdo,$delivery,$status,'Status updated');if($status==='delivered')$pdo->prepare("UPDATE orders SET status='completed' WHERE id=(SELECT order_id FROM deliveries WHERE id=?)")->execute([$delivery]);
        flash('Delivery status updated.');op_redirect_delivery($role,$delivery);
    }
    if ($action==='gps_update') {
        header('Content-Type: application/json; charset=utf-8');$delivery=(int)($_POST['delivery_id']??0);$lat=filter_var($_POST['latitude']??null,FILTER_VALIDATE_FLOAT);$lon=filter_var($_POST['longitude']??null,FILTER_VALIDATE_FLOAT);if($lat===false||$lon===false||abs($lat)>90||abs($lon)>180){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Invalid coordinates']);exit;}
        $s=$pdo->prepare("SELECT d.id,d.destination_latitude,d.destination_longitude,r.id rider_id FROM deliveries d JOIN delivery_riders r ON r.id=d.rider_id WHERE d.id=? AND d.owner_id=? AND r.user_id=? AND d.status='out_for_delivery'");$s->execute([$delivery,$owner,user_id()]);$d=$s->fetch();if(!$d){http_response_code(403);echo json_encode(['ok'=>false,'message'=>'GPS updates are accepted only for your active delivery']);exit;}
        $pdo->beginTransaction();try{$pdo->prepare('INSERT INTO delivery_locations(delivery_id,rider_id,latitude,longitude) VALUES(?,?,?,?)')->execute([$delivery,$d['rider_id'],$lat,$lon]);$eta=null;if($d['destination_latitude']!==null&&$d['destination_longitude']!==null){$km=op_haversine((float)$lat,(float)$lon,(float)$d['destination_latitude'],(float)$d['destination_longitude']);$eta=date('Y-m-d H:i:s',time()+(int)round(($km/ETA_ASSUMED_SPEED_KMH)*3600));$pdo->prepare('UPDATE deliveries SET current_latitude=?,current_longitude=?,last_location_at=NOW(),route_distance_km=?,eta_at=? WHERE id=?')->execute([$lat,$lon,$km,$eta,$delivery]);}else{$pdo->prepare('UPDATE deliveries SET current_latitude=?,current_longitude=?,last_location_at=NOW(),eta_at=NULL WHERE id=?')->execute([$lat,$lon,$delivery]);}$pdo->commit();echo json_encode(['ok'=>true,'updated_at'=>date(DATE_ATOM),'eta'=>$eta,'distance_km'=>isset($km)?round($km,2):null]);}catch(Throwable $e){$pdo->rollBack();error_log('GPS update failed: '.$e->getMessage());http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Could not save location']);}exit;
    }
    if ($action==='exception_report') {
        $delivery=(int)($_POST['delivery_id']??0);$cat=(string)($_POST['category']??'other');$desc=field('description',1000);$categories=['customer_unavailable','incorrect_address','cannot_reach','transport_problem','delayed','customer_cancelled','other'];if(!in_array($cat,$categories,true)||$desc===''){flash('Choose an exception type and add a description.');redirect('rider_dashboard');}
        $s=$pdo->prepare('SELECT d.id,r.id rider_id FROM deliveries d JOIN delivery_riders r ON r.id=d.rider_id WHERE d.id=? AND d.owner_id=? AND r.user_id=?');$s->execute([$delivery,$owner,user_id()]);$d=$s->fetch();if(!$d){http_response_code(403);exit('Delivery not assigned to this rider.');}
        $pdo->prepare('INSERT INTO delivery_exceptions(delivery_id,rider_id,category,description,latitude,longitude) SELECT ?,?,?,?,current_latitude,current_longitude FROM deliveries WHERE id=? AND owner_id=?')->execute([$delivery,$d['rider_id'],$cat,$desc,$delivery,$owner]);$pdo->prepare("UPDATE deliveries SET status='exception' WHERE id=? AND owner_id=?")->execute([$delivery,$owner]);op_record_event($pdo,$delivery,'exception',$cat.': '.$desc);flash('Delivery exception reported to the administrator.');redirect('rider_dashboard');
    }
    if ($action==='exception_resolve') { $pdo->prepare('UPDATE delivery_exceptions x JOIN deliveries d ON d.id=x.delivery_id SET x.resolved_at=NOW(),x.resolved_by=? WHERE x.id=? AND d.owner_id=? AND x.resolved_at IS NULL')->execute([user_id(),(int)$_POST['id'],$owner]);flash('Exception marked as resolved.');redirect('deliveries'); }
    return true;
}

function op_haversine(float $lat1,float $lon1,float $lat2,float $lon2):float
{
    $r=6371;$dLat=deg2rad($lat2-$lat1);$dLon=deg2rad($lon2-$lon1);$a=sin($dLat/2)**2+cos(deg2rad($lat1))*cos(deg2rad($lat2))*sin($dLon/2)**2;return 2*$r*asin(min(1,sqrt($a)));
}

function op_tracking_snapshot(PDO $pdo,string $token):?array
{
    if(strlen($token)<24||strlen($token)>128)return null;
    $s=$pdo->prepare("SELECT d.id,d.tracking_code,d.status,d.current_latitude,d.current_longitude,d.destination_latitude,d.destination_longitude,d.eta_at,d.last_location_at,d.updated_at,o.order_number,o.delivery_address,c.full_name customer,ru.name rider_name,r.phone rider_phone FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users ru ON ru.id=r.user_id WHERE d.tracking_token_hash=?");$s->execute([hash('sha256',$token)]);$d=$s->fetch();return $d?:null;
}

function op_json_snapshot(PDO $pdo,string $token):never
{
    header('Content-Type: application/json; charset=utf-8');$d=op_tracking_snapshot($pdo,$token);if(!$d){http_response_code(404);echo json_encode(['ok'=>false]);exit;}$events=rows($pdo,'SELECT status,note,created_at FROM delivery_events WHERE delivery_id=? ORDER BY created_at,id',[$d['id']]);echo json_encode(['ok'=>true,'delivery'=>$d,'events'=>$events]);exit;
}

function op_json_admin_snapshot(PDO $pdo,int $id):never
{
    require_login();if(($_SESSION['role']??'admin')!=='admin'){http_response_code(403);exit;}$s=$pdo->prepare('SELECT d.id,d.tracking_code,d.status,d.current_latitude,d.current_longitude,d.destination_latitude,d.destination_longitude,d.eta_at,d.last_location_at,o.order_number,o.delivery_address,c.full_name customer,u.name rider_name FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users u ON u.id=r.user_id WHERE d.id=? AND d.owner_id=?');$s->execute([$id,user_id()]);$d=$s->fetch();if(!$d){http_response_code(404);echo json_encode(['ok'=>false]);exit;}$d['events']=rows($pdo,'SELECT status,created_at,note FROM delivery_events WHERE delivery_id=? ORDER BY created_at,id',[$id]);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'delivery'=>$d]);exit;
}

function op_handle_export(PDO $pdo,string $format):never
{
    op_admin();$owner=user_id();$map=[
        'orders_csv'=>['SELECT o.order_number,c.full_name customer,o.status,o.payment_status,o.payment_method,o.subtotal,o.delivery_fee,o.discount,o.total_amount,o.ordered_at FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.owner_id=? ORDER BY o.ordered_at DESC','orders.csv'],
        'customers_csv'=>['SELECT full_name,email,phone,status,created_at FROM customers WHERE owner_id=? ORDER BY created_at DESC','customers.csv'],
        'deliveries_csv'=>['SELECT d.tracking_code,o.order_number,c.full_name customer,d.status,d.scheduled_at,d.eta_at,d.last_location_at FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id WHERE d.owner_id=? ORDER BY d.created_at DESC','deliveries.csv']
    ];if(!isset($map[$format])){http_response_code(404);exit('Unknown export.');}[$sql,$filename]=$map[$format];$headers=match($format){'orders_csv'=>['Order','Customer','Status','Payment status','Payment method','Subtotal','Delivery fee','Discount','Total','Ordered at'],'customers_csv'=>['Name','Email','Phone','Status','Registered'],'deliveries_csv'=>['Tracking ID','Order','Customer','Status','Scheduled','ETA','Last GPS update']};$s=$pdo->prepare($sql);$s->execute([$owner]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename='.$filename);$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);while($row=$s->fetch(PDO::FETCH_NUM))fputcsv($out,$row);fclose($out);exit;
}

function op_render_map(PDO $pdo,array $d,string $mode='admin'):void
{
    $mapId='delivery-map-'.(int)$d['id'].'-'.substr($mode,0,1);$token=(string)($d['tracking_token']??'');
    echo '<div class="map-frame" id="'.h($mapId).'" data-delivery-id="'.(int)$d['id'].'" data-track-token="'.h($token).'" data-mode="'.h($mode).'" data-lat="'.h($d['current_latitude']??'').'" data-lon="'.h($d['current_longitude']??'').'" data-dest-lat="'.h($d['destination_latitude']??'').'" data-dest-lon="'.h($d['destination_longitude']??'').'">';
    if($d['current_latitude']===null && $d['destination_latitude']===null)echo '<div class="map-empty">Location data will appear when the rider shares GPS during an active delivery.</div>';
    echo '</div>';
}

function op_render_orders(PDO $pdo,int $owner):void
{
    [$ordersThis,$ordersLast]=op_period_status_counts($pdo,'orders','ordered_at',$owner);
    $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$payment=(string)($_GET['payment']??'');$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$sort=(string)($_GET['sort']??'ordered_at');$dir=strtolower((string)($_GET['dir']??'desc'))==='asc'?'ASC':'DESC';$allowed=['order_number'=>'o.order_number','customer'=>'c.full_name','total'=>'o.total_amount','status'=>'o.status','ordered_at'=>'o.ordered_at'];$order=$allowed[$sort]??$allowed['ordered_at'];$page=max(1,(int)($_GET['p']??1));$per=15;$where='o.owner_id=?';$args=[$owner];
    if($q!==''){$where.=' AND (o.order_number LIKE ? OR c.full_name LIKE ?)';$args[]="%$q%";$args[]="%$q%";}if(in_array($status,['pending','processing','completed','cancelled'],true)){$where.=' AND o.status=?';$args[]=$status;}if(in_array($payment,['pending','paid','failed','refunded'],true)){$where.=' AND o.payment_status=?';$args[]=$payment;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND DATE(o.ordered_at)>=?';$args[]=$from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND DATE(o.ordered_at)<=?';$args[]=$to;}
    $s=$pdo->prepare("SELECT COUNT(*) FROM orders o JOIN customers c ON c.id=o.customer_id WHERE $where");$s->execute($args);$count=(int)$s->fetchColumn();$pages=max(1,(int)ceil($count/$per));$page=min($page,$pages);$s=$pdo->prepare("SELECT o.*,c.full_name customer,(SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) items,d.id delivery_id,d.status delivery_status FROM orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN deliveries d ON d.order_id=o.id WHERE $where ORDER BY $order $dir LIMIT $per OFFSET ".(($page-1)*$per));$s->execute($args);$list=$s->fetchAll();
    $tot=rows($pdo,'SELECT COUNT(*) total,SUM(status=\'completed\') completed,SUM(status=\'cancelled\') cancelled,SUM(status=\'pending\') pending FROM orders WHERE owner_id=?',[$owner])[0];$src=rows($pdo,'SELECT source,COUNT(*) amount FROM orders WHERE owner_id=? GROUP BY source',[$owner]);$sources=['website'=>0,'mobile'=>0,'in_store'=>0];foreach($src as $x)$sources[$x['source']]=(int)$x['amount'];$sourceTotal=array_sum($sources);$web=$sourceTotal?round($sources['website']/$sourceTotal*100):0;$mob=$sourceTotal?round($sources['mobile']/$sourceTotal*100):0;$store=$sourceTotal?max(0,100-$web-$mob):0;
    $customers=rows($pdo,"SELECT id,full_name FROM customers WHERE owner_id=? AND status='active' ORDER BY full_name",[$owner]);$products=rows($pdo,'SELECT id,name,unit_cost,quantity FROM products WHERE user_id=? ORDER BY name',[$owner]);$export='?export=orders_csv';
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> SALES OPERATIONS</div><h1>Orders</h1><p>Search orders and monitor fulfillment from one place.</p></div><div class="heading-actions"><a class="button primary" href="#new-order">＋ Create order</a><a class="button export-button" href="<?=$export?>">Export ↓</a></div></div>
    <section class="ops-stats"><article><span>Total Orders</span><b><?=number_format((int)$tot['total'])?></b><small><?=h(op_period_change($ordersThis,$ordersLast))?> vs last month</small><i class="metric-icon blue">▣</i></article><article><span>Orders Completed</span><b><?=number_format((int)$tot['completed'])?></b><small><?=h(op_period_change($ordersThis,$ordersLast,'completed'))?> vs last month</small><i class="metric-icon green">✓</i></article><article><span>Orders Cancelled</span><b><?=number_format((int)$tot['cancelled'])?></b><small><?=h(op_period_change($ordersThis,$ordersLast,'cancelled'))?> vs last month</small><i class="metric-icon pink">×</i></article><article><span>Orders Pending</span><b><?=number_format((int)$tot['pending'])?></b><small><?=h(op_period_change($ordersThis,$ordersLast,'pending'))?> vs last month</small><i class="metric-icon yellow">◷</i></article></section>
    <section class="order-overview"><div class="panel source-panel"><div class="panel-heading"><div><h2>Order Sources Overview</h2><p>Distribution across your recorded orders</p></div><span class="range-chip">All time</span></div><div class="donut-wrap"><div class="donut" style="--web:<?=$web?>%;--mobile:<?=$web+$mob?>%"><span><?=number_format($sourceTotal)?><small>Total Orders</small></span></div><div class="donut-legend"><div><i class="source-web"></i><span>Website Orders (<?=$web?>%)</span><b><?=number_format($sources['website'])?></b></div><div><i class="source-mobile"></i><span>Mobile App Orders (<?=$mob?>%)</span><b><?=number_format($sources['mobile'])?></b></div><div><i class="source-store"></i><span>In-Store Orders (<?=$store?>%)</span><b><?=number_format($sources['in_store'])?></b></div></div></div></div>
    <div class="panel order-spark"><h2>Order status</h2><p>Current order records</p><div class="status-bars"><div><i style="height:<?=max(3,(int)$tot['completed']*10)?>%"></i><span>Complete</span></div><div><i style="height:<?=max(3,(int)$tot['pending']*10)?>%"></i><span>Pending</span></div><div><i style="height:<?=max(3,(int)$tot['cancelled']*10)?>%"></i><span>Cancelled</span></div></div><a class="text-link" href="#order-table">Review order list →</a></div></section>
    <div class="panel table-panel" id="order-table"><div class="panel-heading"><div><h2>Orders Management</h2><p><?=number_format($count)?> matching order<?=($count===1?'':'s')?></p></div></div><form class="ops-filter" method="get"><input type="hidden" name="page" value="orders"><input name="q" value="<?=h($q)?>" placeholder="Search order or customer"><select name="status"><option value="">All order statuses</option><?php foreach(['pending','processing','completed','cancelled'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select><select name="payment"><option value="">All payment statuses</option><?php foreach(['pending','paid','failed','refunded'] as $x):?><option value="<?=$x?>" <?=$payment===$x?'selected':''?>><?=h(ucfirst($x))?></option><?php endforeach;?></select><input type="date" name="from" value="<?=h($from)?>"><input type="date" name="to" value="<?=h($to)?>"><button class="button primary small">Filter</button></form><div class="table-scroll"><table class="ops-table"><thead><tr><th><a href="?page=orders&sort=order_number&dir=<?=$dir==='ASC'?'desc':'asc'?>">ORDER ID ↕</a></th><th><a href="?page=orders&sort=customer">CUSTOMER</a></th><th>ITEMS</th><th><a href="?page=orders&sort=total">AMOUNT</a></th><th>PAYMENT</th><th><a href="?page=orders&sort=status">STATUS</a></th><th><a href="?page=orders&sort=ordered_at">ORDER DATE</a></th><th>ACTION</th></tr></thead><tbody><?php if(!$list):?><tr><td colspan="8" class="empty-cell">No orders match these filters. Create an order to begin.</td></tr><?php endif;foreach($list as $o):?><tr><td><b><?=h($o['order_number'])?></b></td><td><?=h($o['customer'])?></td><td><?=number_format((int)$o['items'])?></td><td><?=number_format((float)$o['total_amount'],2)?></td><td><span class="status-tag <?=h($o['payment_status'])?>"><?=h(ucfirst($o['payment_status']))?></span><small class="cell-sub"><?=h($o['payment_method']?:'—')?></small></td><td><span class="status-tag <?=h($o['status'])?>"><?=h(op_status_label($o['status']))?></span></td><td><?=h($o['ordered_at'])?></td><td><a class="table-action" href="?page=order_view&id=<?=(int)$o['id']?>">View details →</a></td></tr><?php endforeach;?></tbody></table></div><?=op_pager($page,$pages,'orders')?>
    <form class="inline-create" method="post" id="new-order"><?=form_token()?><input type="hidden" name="action" value="order_create"><div class="panel-heading"><div><h2>Create an order</h2><p>Creates an order, delivery tracking record, secure customer link and one-time proof code.</p></div></div><div class="ops-form-grid"><label>Customer<select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=h($c['full_name'])?></option><?php endforeach;?></select></label><div class="span-all"><div id="order-lines" class="order-lines"><div class="order-line"><label>Product<select name="product_id[]" class="order-product" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" data-price="<?=h($p['unit_cost'])?>"><?=h($p['name'])?> (stock <?=h($p['quantity'])?>)</option><?php endforeach;?></select></label><label>Quantity<input name="quantity[]" type="number" step="0.001" min="0.001" value="1" required></label><label>Unit price<input name="unit_price[]" class="order-price" type="number" step="0.01" min="0" value="0" required></label><button type="button" class="remove-order-line">Remove</button></div></div><template id="order-line-template"><div class="order-line"><label>Product<select name="product_id[]" class="order-product" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" data-price="<?=h($p['unit_cost'])?>"><?=h($p['name'])?> (stock <?=h($p['quantity'])?>)</option><?php endforeach;?></select></label><label>Quantity<input name="quantity[]" type="number" step="0.001" min="0.001" value="1" required></label><label>Unit price<input name="unit_price[]" class="order-price" type="number" step="0.01" min="0" value="0" required></label><button type="button" class="remove-order-line">Remove</button></div></template><button type="button" id="add-order-line" class="button outline small">＋ Add another product</button></div><label>Delivery fee<input name="delivery_fee" type="number" step="0.01" min="0" value="0"></label><label>Discount<input name="discount" type="number" step="0.01" min="0" value="0"></label><label>Order source<select name="source"><option value="in_store">In store</option><option value="website">Website</option><option value="mobile">Mobile app</option></select></label><label>Payment method<input name="payment_method" maxlength="60" placeholder="Cash, M-Pesa..."></label><label>Payment status<select name="payment_status"><option value="pending">Pending</option><option value="paid">Paid</option></select></label><label>Departure location<input name="departure_location" maxlength="250" placeholder="Store / dispatch address"></label><label class="span-all">Delivery address<input name="delivery_address" maxlength="500" required></label><label>Destination latitude (optional)<input name="destination_latitude" type="number" step="any" min="-90" max="90"></label><label>Destination longitude (optional)<input name="destination_longitude" type="number" step="any" min="-180" max="180"></label></div><p class="muted microcopy">Coordinates must come from a known address or customer-provided location. If left blank, map and ETA remain unavailable until location details are supplied.</p><button class="button primary">Create order & tracking</button></form></div>
