function op_pager(int $page,int $pages,string $route):string
{
    if($pages<=1)return '';return '<div class="pager"><span>Page '.(int)$page.' of '.(int)$pages.'</span><div>'.($page>1?'<a href="?page='.h($route).'&p='.($page-1).'">← Previous</a>':'').($page<$pages?'<a href="?page='.h($route).'&p='.($page+1).'">Next →</a>':'').'</div></div>';
}

function op_render_customers(PDO $pdo,int $owner):void
{
    $customerGrowth=op_customer_growth($pdo,$owner);
    $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$sort=(string)($_GET['sort']??'registered');$dir=strtolower((string)($_GET['dir']??'desc'))==='asc'?'ASC':'DESC';$customerSort=['name'=>'c.full_name','email'=>'c.email','orders'=>'total_orders','spending'=>'spending','status'=>'c.status','registered'=>'c.created_at'];$orderBy=$customerSort[$sort]??$customerSort['registered'];$page=max(1,(int)($_GET['p']??1));$per=15;$where='c.owner_id=?';$args=[$owner];if($q!==''){$where.=' AND (c.full_name LIKE ? OR c.email LIKE ? OR c.phone LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}if(in_array($status,['active','inactive'],true)){$where.=' AND c.status=?';$args[]=$status;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND DATE(c.created_at)>=?';$args[]=$from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND DATE(c.created_at)<=?';$args[]=$to;}
    $s=$pdo->prepare("SELECT COUNT(*) FROM customers c WHERE $where");$s->execute($args);$count=(int)$s->fetchColumn();$pages=max(1,(int)ceil($count/$per));$page=min($page,$pages);$s=$pdo->prepare("SELECT c.*,COUNT(DISTINCT o.id) total_orders,COALESCE(SUM(o.total_amount),0) spending FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.owner_id=c.owner_id WHERE $where GROUP BY c.id ORDER BY $orderBy $dir LIMIT $per OFFSET ".(($page-1)*$per));$s->execute($args);$list=$s->fetchAll();$stats=rows($pdo,"SELECT COUNT(*) total,SUM(status='active') active,SUM(status='inactive') inactive,SUM(created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')) new_month FROM customers WHERE owner_id=?",[$owner])[0];
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> CUSTOMER RELATIONSHIPS</div><h1>Customers</h1><p>Customer profiles and purchase history from this store.</p></div><div class="heading-actions"><a class="button export-button" href="?export=customers_csv">Export ↓</a></div></div><section class="ops-stats"><article><span>Total Customers</span><b><?=number_format((int)$stats['total'])?></b><small>Registered customers</small><i class="metric-icon blue">♙</i></article><article><span>Active Customers</span><b><?=number_format((int)$stats['active'])?></b><small>Can place orders</small><i class="metric-icon green">✓</i></article><article><span>New This Month</span><b><?=number_format((int)$stats['new_month'])?></b><small><?=h($customerGrowth)?> vs last month</small><i class="metric-icon pink">＋</i></article><article><span>Inactive Customers</span><b><?=number_format((int)$stats['inactive'])?></b><small>Currently inactive</small><i class="metric-icon yellow">◷</i></article></section><div class="panel table-panel"><div class="panel-heading"><div><h2>Customer directory</h2><p><?=number_format($count)?> matching customers</p></div></div><form class="ops-filter" method="get"><input type="hidden" name="page" value="customers"><input name="q" value="<?=h($q)?>" placeholder="Search name, email or phone"><select name="status"><option value="">All account statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactive</option></select><input type="date" name="from" value="<?=h($from)?>"><input type="date" name="to" value="<?=h($to)?>"><button class="button primary small">Filter</button></form><div class="table-scroll"><table class="ops-table"><thead><tr><th>CUSTOMER ID</th><th>NAME</th><th>EMAIL</th><th>PHONE</th><th>TOTAL ORDERS</th><th>TOTAL SPENDING</th><th><a href="?page=customers&sort=status">STATUS ↕</a></th><th>ACTION</th></tr></thead><tbody><?php if(!$list):?><tr><td colspan="8" class="empty-cell">No customers yet. Add a customer below to start recording orders.</td></tr><?php endif;foreach($list as $c):?><tr><td>#C<?=str_pad((string)$c['id'],5,'0',STR_PAD_LEFT)?></td><td><b><?=h($c['full_name'])?></b></td><td><?=h($c['email']?:'—')?></td><td><?=h($c['phone']?:'—')?></td><td><?=number_format((int)$c['total_orders'])?></td><td><?=number_format((float)$c['spending'],2)?></td><td><span class="status-tag <?=h($c['status'])?>"><?=h(ucfirst($c['status']))?></span></td><td><a class="table-action" href="?page=customer_view&id=<?=(int)$c['id']?>">View profile →</a></td></tr><?php endforeach;?></tbody></table></div><?=op_pager($page,$pages,'customers')?></div><form class="panel inline-create" method="post"><?=form_token()?><input type="hidden" name="action" value="customer_save"><div class="panel-heading"><div><h2>Add customer</h2><p>Customer and delivery address details</p></div></div><div class="ops-form-grid"><label>Full name<input name="full_name" required maxlength="160"></label><label>Email<input type="email" name="email" maxlength="190"></label><label>Phone<input name="phone" maxlength="40"></label><label>Address label<input name="address_label" value="Home" maxlength="80"></label><label class="span-all">Delivery address<input name="address" maxlength="500"></label></div><button class="button primary">Save customer</button></form><?php
}

function op_render_customer_view(PDO $pdo,int $owner,int $id):void
{
    $s=$pdo->prepare('SELECT * FROM customers WHERE id=? AND owner_id=?');$s->execute([$id,$owner]);$c=$s->fetch();if(!$c){echo '<div class="empty-cell">Customer not found.</div>';return;}$orders=rows($pdo,'SELECT o.*,d.status delivery_status FROM orders o LEFT JOIN deliveries d ON d.order_id=o.id WHERE o.customer_id=? AND o.owner_id=? ORDER BY o.ordered_at DESC',[$id,$owner]);$addresses=rows($pdo,'SELECT * FROM customer_addresses WHERE customer_id=? ORDER BY is_default DESC,id',[$id]);$stats=rows($pdo,'SELECT COUNT(*) total,COALESCE(SUM(total_amount),0) spending,COALESCE(AVG(total_amount),0) average FROM orders WHERE customer_id=? AND owner_id=?',[$id,$owner])[0];$favorites=rows($pdo,'SELECT oi.product_name,SUM(oi.quantity) quantity FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.customer_id=? AND o.owner_id=? GROUP BY oi.product_name ORDER BY quantity DESC LIMIT 5',[$id,$owner]);
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> CUSTOMER PROFILE</div><h1><?=h($c['full_name'])?></h1><p>Customer since <?=h(substr($c['created_at'],0,10))?></p></div><form method="post"><?=form_token()?><input type="hidden" name="action" value="customer_toggle"><input type="hidden" name="id" value="<?=(int)$id?>"><button class="button <?=$c['status']==='active'?'outline':'primary'?> small">Set <?= $c['status']==='active'?'inactive':'active' ?></button></form></div><section class="ops-stats profile-stats"><article><span>Total Orders</span><b><?=number_format((int)$stats['total'])?></b></article><article><span>Total Spending</span><b><?=number_format((float)$stats['spending'],2)?></b></article><article><span>Average Order</span><b><?=number_format((float)$stats['average'],2)?></b></article><article><span>Account status</span><b><?=h(ucfirst($c['status']))?></b></article></section><div class="profile-grid"><section class="panel"><h2>Customer information</h2><p><?=h($c['email']?:'No email recorded')?><br><?=h($c['phone']?:'No phone recorded')?></p></section><section class="panel"><h2>Delivery addresses</h2><?php if(!$addresses):?><p class="muted">No saved addresses.</p><?php endif;foreach($addresses as $a):?><p><b><?=h($a['label'])?></b> <?= $a['is_default']?'<span class="range-chip">Default</span>':'' ?><br><?=h($a['address_text'])?></p><?php endforeach;?></section><section class="panel"><h2>Frequently purchased products</h2><?php if(!$favorites):?><p class="muted">Purchase history will appear here.</p><?php endif;foreach($favorites as $f):?><p><?=h($f['product_name'])?> <span class="range-chip"><?=h($f['quantity'])?> purchased</span></p><?php endforeach;?></section></div><div class="panel table-panel"><div class="panel-heading"><div><h2>Order history</h2><p>Actual orders associated with this customer</p></div></div><div class="table-scroll"><table class="ops-table"><thead><tr><th>ORDER</th><th>DATE</th><th>AMOUNT</th><th>PAYMENT</th><th>DELIVERY</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="6" class="empty-cell">No orders recorded for this customer.</td></tr><?php endif;foreach($orders as $o):?><tr><td><?=h($o['order_number'])?></td><td><?=h($o['ordered_at'])?></td><td><?=number_format((float)$o['total_amount'],2)?></td><td><?=h(ucfirst($o['payment_status']))?></td><td><?=h($o['delivery_status']?op_status_label($o['delivery_status']):'—')?></td><td><a class="table-action" href="?page=order_view&id=<?=(int)$o['id']?>">View →</a></td></tr><?php endforeach;?></tbody></table></div></div><a class="text-link" href="?page=customers">← Back to customers</a><?php
}

function op_render_order_view(PDO $pdo,int $owner,int $id):void
{
    $s=$pdo->prepare('SELECT o.*,c.full_name customer,c.email,c.phone,d.id delivery_id,d.tracking_code,d.status delivery_status,d.eta_at,d.last_location_at,d.current_latitude,d.current_longitude,d.destination_latitude,d.destination_longitude,d.proof_code_hash FROM orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN deliveries d ON d.order_id=o.id WHERE o.id=? AND o.owner_id=?');$s->execute([$id,$owner]);$o=$s->fetch();if(!$o){echo '<div class="empty-cell">Order not found.</div>';return;}$items=rows($pdo,'SELECT product_name,quantity,unit_price,line_total FROM order_items WHERE order_id=?',[$id]);$events=$o['delivery_id']?rows($pdo,'SELECT status,note,created_at FROM delivery_events WHERE delivery_id=? ORDER BY created_at,id',[$o['delivery_id']]):[];$riders=rows($pdo,'SELECT r.id,u.name,r.phone,r.availability,COUNT(d.id) workload FROM delivery_riders r JOIN users u ON u.id=r.user_id LEFT JOIN deliveries d ON d.rider_id=r.id AND d.status NOT IN (\'delivered\',\'cancelled\',\'returned\') WHERE r.owner_id=? GROUP BY r.id ORDER BY r.availability DESC,u.name',[$owner]);
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> ORDER DETAILS</div><h1><?=h($o['order_number'])?></h1><p><?=h($o['ordered_at'])?> · <?=h($o['customer'])?></p></div><a class="button outline small" href="?page=orders">← Orders</a></div><div class="profile-grid"><section class="panel"><h2>Customer</h2><p><?=h($o['customer'])?><br><?=h($o['email']?:'—')?> · <?=h($o['phone']?:'—')?></p><h2>Delivery address</h2><p><?=h($o['delivery_address']?:'No delivery address recorded')?></p><h2>Payment</h2><p><?=h(ucfirst($o['payment_status']))?> · <?=h($o['payment_method']?:'Method not recorded')?></p></section><section class="panel"><h2>Order totals</h2><p>Subtotal <b class="float-right"><?=number_format((float)$o['subtotal'],2)?></b></p><p>Delivery fee <b class="float-right"><?=number_format((float)$o['delivery_fee'],2)?></b></p><p>Discount <b class="float-right">−<?=number_format((float)$o['discount'],2)?></b></p><hr><p>Final amount <b class="float-right"><?=number_format((float)$o['total_amount'],2)?></b></p><form method="post" class="ops-inline-form"><?=form_token()?><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=(int)$id?>"><select name="status"><?php foreach(['pending','processing','completed','cancelled'] as $x):?><option value="<?=$x?>" <?=$o['status']===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select><button class="button primary small">Update order status</button></form></section></div><section class="panel table-panel"><h2>Ordered products</h2><div class="table-scroll"><table class="ops-table"><thead><tr><th>PRODUCT</th><th>QUANTITY</th><th>UNIT PRICE</th><th>LINE TOTAL</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=h($i['quantity'])?></td><td><?=number_format((float)$i['unit_price'],2)?></td><td><?=number_format((float)$i['line_total'],2)?></td></tr><?php endforeach;?></tbody></table></div></section><?php if($o['delivery_id']):?><section class="panel table-panel"><div class="panel-heading"><div><h2>Delivery · <?=h($o['tracking_code'])?></h2><p><?=h(op_status_label($o['delivery_status']))?> · <?= $o['eta_at']?'Estimated arrival '.h($o['eta_at']):'ETA unavailable until actual GPS and destination coordinates are available' ?></p></div></div><?php op_render_map($pdo,$o); ?><form method="post" class="assign-form"><?=form_token()?><input type="hidden" name="action" value="delivery_assign"><input type="hidden" name="delivery_id" value="<?=(int)$o['delivery_id']?>"><select name="rider_id" required><option value="">Assign / reassign rider</option><?php foreach($riders as $r):?><option value="<?=(int)$r['id']?>"><?=h($r['name'])?> · <?=h($r['availability'])?> · <?=number_format((int)$r['workload'])?> active</option><?php endforeach;?></select><label class="override-label"><input type="checkbox" name="override_unavailable"> Override unavailable rider</label><button class="button primary small">Save assignment</button></form><form method="post" class="ops-inline-form proof-form"><?=form_token()?><input type="hidden" name="action" value="delivery_status"><input type="hidden" name="delivery_id" value="<?=(int)$o['delivery_id']?>"><select name="status"><?php foreach(['accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','returned','failed'] as $x):?><option value="<?=$x?>" <?=$o['delivery_status']===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select><input name="proof_code" inputmode="numeric" maxlength="6" placeholder="Customer proof code for delivery"><button class="button primary small">Update delivery</button></form><ol class="timeline"><?php foreach($events as $e):?><li><i></i><div><b><?=h(op_status_label($e['status']))?></b><small><?=h($e['created_at'])?> <?=h($e['note']?:'')?></small></div></li><?php endforeach;?></ol></section><?php endif;?><?php
}

function op_render_deliveries(PDO $pdo,int $owner):void
{
    [$deliveryThis,$deliveryLast]=op_period_status_counts($pdo,'deliveries','created_at',$owner);$deliveryPerformance=op_delivery_performance($pdo,$owner);$riderStats=rows($pdo,"SELECT u.name,COUNT(d.id) assigned,COALESCE(SUM(d.status='delivered'),0) completed FROM delivery_riders r JOIN users u ON u.id=r.user_id LEFT JOIN deliveries d ON d.rider_id=r.id WHERE r.owner_id=? GROUP BY r.id ORDER BY completed DESC",[$owner]);
    $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$sort=(string)($_GET['sort']??'date');$dir=strtolower((string)($_GET['dir']??'desc'))==='asc'?'ASC':'DESC';$sortColumns=['order'=>'o.order_number','customer'=>'c.full_name','date'=>'d.created_at','rider'=>'ru.name','status'=>'d.status'];$orderBy=$sortColumns[$sort]??$sortColumns['date'];$page=max(1,(int)($_GET['p']??1));$per=12;$where='d.owner_id=?';$args=[$owner];if($q!==''){$where.=' AND (o.order_number LIKE ? OR c.full_name LIKE ? OR d.tracking_code LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}if(in_array($status,['assigned','accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','cancelled','returned','failed','exception'],true)){$where.=' AND d.status=?';$args[]=$status;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND DATE(d.created_at)>=?';$args[]=$from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND DATE(d.created_at)<=?';$args[]=$to;}
    $s=$pdo->prepare("SELECT COUNT(*) FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users ru ON ru.id=r.user_id WHERE $where");$s->execute($args);$count=(int)$s->fetchColumn();$pages=max(1,(int)ceil($count/$per));$page=min($page,$pages);$s=$pdo->prepare("SELECT d.*,o.order_number,o.ordered_at,o.departure_location,o.delivery_address,c.full_name customer,c.phone,r.id rider_id,ru.name rider_name,r.phone rider_phone FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users ru ON ru.id=r.user_id WHERE $where ORDER BY $orderBy $dir LIMIT $per OFFSET ".(($page-1)*$per));$s->execute($args);$list=$s->fetchAll();$stats=rows($pdo,"SELECT COUNT(*) total,SUM(status='delivered') delivered,SUM(status IN ('accepted','preparing','ready_for_pickup','picked_up','out_for_delivery')) active,SUM(status='cancelled') cancelled,SUM(status='returned') returned FROM deliveries WHERE owner_id=?",[$owner])[0];$riders=rows($pdo,'SELECT r.*,u.name,u.email,(SELECT COUNT(*) FROM deliveries d WHERE d.rider_id=r.id AND d.status NOT IN (\'delivered\',\'cancelled\',\'returned\')) workload FROM delivery_riders r JOIN users u ON u.id=r.user_id WHERE r.owner_id=? ORDER BY r.availability DESC,u.name',[$owner]);$active=rows($pdo,"SELECT d.*,o.order_number,o.departure_location,o.delivery_address,c.full_name customer,r.phone rider_phone,u.name rider_name FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users u ON u.id=r.user_id WHERE d.owner_id=? AND d.status IN ('accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','exception') ORDER BY d.updated_at DESC LIMIT 1",[$owner]);
    $months=rows($pdo,"SELECT DATE_FORMAT(created_at,'%b %y') label,COUNT(*) amount,MIN(created_at) month_order FROM deliveries WHERE owner_id=? AND created_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY YEAR(created_at),MONTH(created_at),label ORDER BY month_order",[$owner]);$maxVol=1;foreach($months as $m)$maxVol=max($maxVol,(int)$m['amount']);$s=$pdo->prepare('SELECT COALESCE(SUM(delivery_fee),0) FROM orders WHERE owner_id=?');$s->execute([$owner]);$revenue=(float)$s->fetchColumn();$exceptions=rows($pdo,'SELECT x.*,o.order_number,c.full_name customer FROM delivery_exceptions x JOIN deliveries d ON d.id=x.delivery_id JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id WHERE d.owner_id=? ORDER BY x.created_at DESC LIMIT 8',[$owner]);
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> FULFILMENT OPERATIONS</div><h1>Deliveries</h1><p>Assign riders and monitor real delivery progress.</p></div><a class="button export-button" href="?export=deliveries_csv">Export ↓</a></div><section class="ops-stats"><article><span>Total Delivered</span><b><?=number_format((int)$stats['delivered'])?></b><small><?=h(op_period_change($deliveryThis,$deliveryLast,'delivered'))?> vs last month</small><i class="metric-icon blue">▣</i></article><article><span>On Delivery</span><b><?=number_format((int)$stats['active'])?></b><small><?=h(op_period_change($deliveryThis,$deliveryLast,'active'))?> vs last month</small><i class="metric-icon green">↗</i></article><article><span>Cancelled Delivery</span><b><?=number_format((int)$stats['cancelled'])?></b><small><?=h(op_period_change($deliveryThis,$deliveryLast,'cancelled'))?> vs last month</small><i class="metric-icon pink">×</i></article><article><span>Return Delivery</span><b><?=number_format((int)$stats['returned'])?></b><small><?=h(op_period_change($deliveryThis,$deliveryLast,'returned'))?> vs last month</small><i class="metric-icon yellow">↶</i></article></section><section class="delivery-panels"><div class="panel shipment-panel"><div class="panel-heading"><div><h2>Shipment analytics</h2><p>Monthly delivery records · last six months</p></div></div><?php if(!$months):?><div class="chart-empty">Delivery analytics will appear when orders are scheduled.</div><?php else:?><div class="monthly-bars"><?php foreach($months as $m):?><div><i style="height:<?=max(4,(int)((int)$m['amount']/$maxVol*100))?>%"></i><b><?=number_format((int)$m['amount'])?></b><small><?=h($m['label'])?></small></div><?php endforeach;?></div><?php endif;?></div><div class="panel revenue-panel"><div class="panel-heading"><div><h2>Shipping revenue</h2><p>Delivery fees on recorded orders</p></div><span class="range-chip">All time</span></div><strong><?=number_format($revenue,2)?></strong><small>Recorded delivery fees</small><div class="revenue-note">Revenue is calculated from order delivery_fee values.</div></div></section>
    <section class="panel delivery-insights"><div class="panel-heading"><div><h2>Delivery performance</h2><p>Calculated from recorded delivery timestamps and GPS points</p></div></div><div class="performance-metrics"><div><small>AVERAGE DELIVERY TIME</small><b><?= $deliveryPerformance['avg_minutes']!==null ? number_format((float)$deliveryPerformance['avg_minutes'],0).' min' : '—' ?></b></div><div><small>ON-TIME DELIVERIES</small><b><?= (int)$deliveryPerformance['delivered']>0 ? number_format((int)$deliveryPerformance['on_time']/(int)$deliveryPerformance['delivered']*100,1).'%' : '—' ?></b></div><div><small>FAILED / EXCEPTION</small><b><?=number_format((int)$deliveryPerformance['failed']+(int)$deliveryPerformance['exceptions'])?></b></div><div><small>AVG. GPS DISTANCE</small><b><?= $deliveryPerformance['avg_distance']!==null ? number_format((float)$deliveryPerformance['avg_distance'],1).' km' : '—' ?></b></div></div><div class="rider-performance"><h3>Deliveries per rider</h3><?php if(!$riderStats):?><p class="muted">Add riders to measure workload and completion rates.</p><?php else:?><div class="table-scroll"><table class="ops-table"><thead><tr><th><a href="?page=deliveries&sort=rider">RIDER ↕</a></th><th>DELIVERIES</th><th>COMPLETED</th><th>COMPLETION RATE</th></tr></thead><tbody><?php foreach($riderStats as $rr):?><tr><td><?=h($rr['name'])?></td><td><?=(int)$rr['assigned']?></td><td><?=(int)$rr['completed']?></td><td><?=(int)$rr['assigned']>0?number_format((int)$rr['completed']/(int)$rr['assigned']*100,1).'%':'—'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></section>
<section class="panel live-panel"><div class="panel-heading"><div><h2>Live Tracking Delivery</h2><p>Active delivery preview · location captured only while rider is on route</p></div><?php if($active):?><a class="table-action" href="?page=delivery_view&id=<?=(int)$active[0]['id']?>">View details →</a><?php endif;?></div><?php if(!$active):?><div class="empty-live"><span class="map-empty-icon">⌖</span><b>No active deliveries</b><p>Create an order and assign a rider to see live tracking here. No location is fabricated.</p><a class="button primary small" href="?page=orders#new-order">Create order</a></div><?php else:$d=$active[0];?><div class="live-layout"><?php op_render_map($pdo,$d);?><div class="delivery-meta"><span class="tracking-label">TRACKING ID <b><?=h($d['tracking_code'])?></b></span><span class="status-tag <?=h($d['status'])?>"><?=h(op_status_label($d['status']))?></span><div class="meta-two"><div><small>DEPARTURE</small><b><?=h($d['departure_location']?:'Not recorded')?></b></div><div><small>DESTINATION</small><b><?=h($d['delivery_address']?:'Not recorded')?></b></div><div><small>RIDER</small><b><?=h($d['rider_name']?:'Not assigned')?></b></div><div><small>ESTIMATED ARRIVAL</small><b><?=h($d['eta_at']?:'Unavailable until GPS and destination coordinates')?></b></div></div><small class="last-updated">Last location update: <?=h($d['last_location_at']?:'No GPS update received')?></small><a class="button outline small" href="?page=delivery_view&id=<?=(int)$d['id']?>">View details →</a></div></div><?php endif;?></section>
    <section class="panel table-panel"><div class="panel-heading"><div><h2>Shipments Activities</h2><p><?=number_format($count)?> matching delivery records</p></div></div><form class="ops-filter" method="get"><input type="hidden" name="page" value="deliveries"><input name="q" value="<?=h($q)?>" placeholder="Search tracking ID, order or customer"><select name="status"><option value="">All delivery statuses</option><?php foreach(['assigned','accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','cancelled','returned','failed','exception'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select><input type="date" name="from" value="<?=h($from)?>"><input type="date" name="to" value="<?=h($to)?>"><button class="button primary small">Filter</button></form><div class="table-scroll"><table class="ops-table"><thead><tr><th><a href="?page=deliveries&sort=order">ORDER ID ↕</a></th><th><a href="?page=deliveries&sort=customer">CUSTOMER ↕</a></th><th><a href="?page=deliveries&sort=date">DELIVERY DATE ↕</a></th><th>DEPARTURE</th><th>DESTINATION</th><th><a href="?page=deliveries&sort=rider">RIDER ↕</a></th><th>ETA</th><th><a href="?page=deliveries&sort=status">STATUS ↕</a></th><th>ACTION</th></tr></thead><tbody><?php if(!$list):?><tr><td colspan="9" class="empty-cell">No delivery records yet. Create an order to open a tracked delivery.</td></tr><?php endif;foreach($list as $d):?><tr><td><?=h($d['order_number'])?><small class="cell-sub"><?=h($d['tracking_code'])?></small></td><td><?=h($d['customer'])?></td><td><?=h($d['scheduled_at']?:$d['ordered_at'])?></td><td><?=h($d['departure_location']?:'—')?></td><td><?=h($d['delivery_address']?:'—')?></td><td><?=h($d['rider_name']?:'Unassigned')?></td><td><?=h($d['eta_at']?:'—')?></td><td><span class="status-tag <?=h($d['status'])?>"><?=h(op_status_label($d['status']))?></span></td><td><a class="table-action" href="?page=delivery_view&id=<?=(int)$d['id']?>">View details →</a></td></tr><?php endforeach;?></tbody></table></div><?=op_pager($page,$pages,'deliveries')?></section>
    <section class="panel table-panel"><div class="panel-heading"><div><h2>Delivery riders</h2><p>Workload counts exclude completed or cancelled work.</p></div></div><div class="table-scroll"><table class="ops-table"><thead><tr><th>RIDER</th><th>CONTACT</th><th>VEHICLE</th><th>AVAILABILITY</th><th>ACTIVE DELIVERIES</th><th></th></tr></thead><tbody><?php if(!$riders):?><tr><td colspan="6" class="empty-cell">No riders have been created.</td></tr><?php endif;foreach($riders as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['phone']?:'—')?> · <?=h($r['email'])?></td><td><?=h($r['vehicle']?:'—')?></td><td><span class="status-tag <?=h($r['availability'])?>"><?=h(ucfirst($r['availability']))?></span></td><td><?=number_format((int)$r['workload'])?></td><td><form method="post"><?=form_token()?><input type="hidden" name="action" value="rider_availability"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="table-action"><?= $r['availability']==='available'?'Mark unavailable':'Mark available' ?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
    <form class="panel inline-create" method="post"><?=form_token()?><input type="hidden" name="action" value="rider_create"><div class="panel-heading"><div><h2>Add a delivery rider</h2><p>Creates a restricted rider login and linked rider record.</p></div></div><div class="ops-form-grid"><label>Name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required maxlength="190"></label><label>Phone<input name="phone" maxlength="40"></label><label>Vehicle<input name="vehicle" maxlength="100" placeholder="Bicycle, motorbike..."></label><label>Temporary password<input name="password" type="password" required minlength="8"></label></div><button class="button primary">Create rider account</button></form>
    <?php if($exceptions):?><section class="panel table-panel"><div class="panel-heading"><div><h2>Delivery exceptions</h2><p>Open reports require administrator review.</p></div></div><div class="table-scroll"><table class="ops-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>EXCEPTION</th><th>DESCRIPTION</th><th>REPORTED</th><th></th></tr></thead><tbody><?php foreach($exceptions as $x):?><tr><td><?=h($x['order_number'])?></td><td><?=h($x['customer'])?></td><td><?=h(op_status_label($x['category']))?></td><td><?=h($x['description'])?></td><td><?=h($x['created_at'])?></td><td><?php if(!$x['resolved_at']):?><form method="post"><?=form_token()?><input type="hidden" name="action" value="exception_resolve"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button class="table-action">Resolve</button></form><?php else:?>Resolved<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php
}

function op_render_delivery_view(PDO $pdo,int $owner,int $id):void
{
    $s=$pdo->prepare('SELECT d.*,o.order_number,o.ordered_at,o.departure_location,o.delivery_address,o.customer_id,c.full_name customer,c.phone customer_phone,c.email,r.id rider_id,r.availability,ru.name rider_name,r.phone rider_phone FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users ru ON ru.id=r.user_id WHERE d.id=? AND d.owner_id=?');$s->execute([$id,$owner]);$d=$s->fetch();if(!$d){echo '<div class="empty-cell">Delivery not found.</div>';return;}$events=rows($pdo,'SELECT * FROM delivery_events WHERE delivery_id=? ORDER BY created_at,id',[$id]);$exceptions=rows($pdo,'SELECT * FROM delivery_exceptions WHERE delivery_id=? ORDER BY created_at DESC',[$id]);$riders=rows($pdo,'SELECT r.id,u.name,r.phone,r.availability,(SELECT COUNT(*) FROM deliveries d2 WHERE d2.rider_id=r.id AND d2.status NOT IN (\'delivered\',\'cancelled\',\'returned\')) workload FROM delivery_riders r JOIN users u ON u.id=r.user_id WHERE r.owner_id=? ORDER BY r.availability DESC,u.name',[$owner]);
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> DELIVERY TRACKING</div><h1><?=h($d['tracking_code'])?></h1><p>Order <?=h($d['order_number'])?> · <?=h(op_status_label($d['status']))?></p></div><a class="button outline small" href="?page=deliveries">← Deliveries</a></div><div class="delivery-detail-grid"><section class="panel map-detail"><div class="panel-heading"><div><h2>Live Tracking Delivery</h2><p>Map updates every 15 seconds while this page is open.</p></div></div><?php op_render_map($pdo,$d);?><div class="live-facts"><span>Rider <b><?=h($d['rider_name']?:'Unassigned')?></b></span><span>Rider contact <b><?=h($d['rider_phone']?:'—')?></b></span><span>Destination <b><?=h($d['delivery_address']?:'Not recorded')?></b></span><span>ETA estimate <b><?=h($d['eta_at']?:'Unavailable — need actual rider GPS and destination coordinates')?></b></span><span>Last GPS update <b><?=h($d['last_location_at']?:'No location received')?></b></span></div></section><aside class="panel detail-side"><h2>Delivery details</h2><p>Customer<br><b><?=h($d['customer'])?></b></p><p>Phone<br><b><?=h($d['customer_phone']?:'—')?></b></p><p>Departure<br><b><?=h($d['departure_location']?:'—')?></b></p><p>Order placed<br><b><?=h($d['ordered_at'])?></b></p><form method="post" class="assign-form"><?=form_token()?><input type="hidden" name="action" value="delivery_assign"><input type="hidden" name="delivery_id" value="<?=(int)$id?>"><label>Assign or reassign rider<select name="rider_id" required><option value="">Choose rider</option><?php foreach($riders as $r):?><option value="<?=(int)$r['id']?>" <?=((int)$d['rider_id']===(int)$r['id'])?'selected':''?>><?=h($r['name'])?> · <?=h($r['availability'])?> · <?=number_format((int)$r['workload'])?> active</option><?php endforeach;?></select></label><label class="override-label"><input type="checkbox" name="override_unavailable"> Override unavailable rider</label><button class="button primary small">Save assignment</button></form><form method="post" class="status-update-form"><?=form_token()?><input type="hidden" name="action" value="delivery_status"><input type="hidden" name="delivery_id" value="<?=(int)$id?>"><label>Update delivery status<select name="status"><?php foreach(['accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered','returned','failed'] as $x):?><option value="<?=$x?>" <?=$d['status']===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select></label><label>Customer proof code<input name="proof_code" inputmode="numeric" maxlength="6" placeholder="Required to mark delivered"></label><button class="button primary small">Update status</button></form></aside></div><section class="panel timeline-panel"><div class="panel-heading"><div><h2>Delivery timeline</h2><p>Recorded status changes with timestamps</p></div></div><?php if(!$events):?><p class="muted">No timeline events yet.</p><?php endif;?><ol class="timeline"><?php foreach($events as $e):?><li><i></i><div><b><?=h(op_status_label($e['status']))?></b><small><?=h($e['created_at'])?> · <?=h($e['note']?:'')?></small></div></li><?php endforeach;?></ol></section><?php if($exceptions):?><section class="panel timeline-panel"><h2>Exception history</h2><?php foreach($exceptions as $x):?><p><span class="status-tag exception"><?=h(op_status_label($x['category']))?></span> <?=h($x['description'])?> <small><?=h($x['created_at'])?> · <?=$x['resolved_at']?'Resolved':'Open'?></small></p><?php endforeach;?></section><?php endif; ?><p class="microcopy">ETA uses straight-line distance from real GPS to the saved destination coordinates at a configurable 25 km/h estimate. It is approximate, not a road route or traffic-aware guarantee.</p><?php
}

function op_render_rider_dashboard(PDO $pdo):void
{
    require_login();if(($_SESSION['role']??'')!=='rider'){http_response_code(403);exit('Rider access required.');}$owner=op_owner();$deliveries=rows($pdo,"SELECT d.*,o.order_number,o.delivery_address,o.departure_location,c.full_name customer,c.phone customer_phone FROM deliveries d JOIN delivery_riders r ON r.id=d.rider_id JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id WHERE r.user_id=? AND d.owner_id=? AND d.status NOT IN ('delivered','cancelled','returned') ORDER BY d.created_at",[user_id(),$owner]);
    ?><div class="page-heading"><div><div class="eyebrow"><i></i> RIDER WORKSPACE</div><h1>Your assigned deliveries</h1><p>Location is requested only after you start an assigned delivery.</p></div></div><?php if(!$deliveries):?><div class="panel empty-live"><b>No assigned deliveries</b><p>Ask your store administrator to assign a delivery to your rider account.</p></div><?php endif;foreach($deliveries as $d):?><section class="panel rider-job"><div class="panel-heading"><div><h2><?=h($d['order_number'])?> · <?=h($d['tracking_code'])?></h2><p><?=h(op_status_label($d['status']))?></p></div></div><div class="rider-job-grid"><div><p>Customer <b><?=h($d['customer'])?></b></p><p>Contact <a href="tel:<?=h($d['customer_phone'])?>"><?=h($d['customer_phone']?:'Not available')?></a></p><p>Destination <b><?=h($d['delivery_address']?:'Not recorded')?></b></p><p>Departure <b><?=h($d['departure_location']?:'—')?></b></p><?php if($d['delivery_address']):?><a class="button outline small" target="_blank" rel="noopener" href="https://www.openstreetmap.org/search?query=<?=rawurlencode($d['delivery_address'])?>">Navigate to destination ↗</a><?php endif;?></div><div><form method="post" class="status-update-form"><?=form_token()?><input type="hidden" name="action" value="rider_delivery_status"><input type="hidden" name="delivery_id" value="<?=(int)$d['id']?>"><label>Progress<select name="status"><?php foreach(['accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','delivered'] as $x):?><option value="<?=$x?>" <?=$d['status']===$x?'selected':''?>><?=h(op_status_label($x))?></option><?php endforeach;?></select></label><label>Customer delivery code<input name="proof_code" inputmode="numeric" maxlength="6" placeholder="Required to complete"></label><button class="button primary small">Save progress</button></form><form method="post" class="exception-form"><?=form_token()?><input type="hidden" name="action" value="exception_report"><input type="hidden" name="delivery_id" value="<?=(int)$d['id']?>"><label>Report an exception<select name="category"><?php foreach(['customer_unavailable','incorrect_address','cannot_reach','transport_problem','delayed','customer_cancelled','other'] as $x):?><option value="<?=$x?>"><?=h(op_status_label($x))?></option><?php endforeach;?></select></label><label>Description<textarea name="description" required maxlength="1000"></textarea></label><button class="button outline small">Report issue</button></form></div></div><div class="gps-controls" data-gps-interval="<?=GPS_UPDATE_INTERVAL_MS?>" data-gps-delivery="<?=(int)$d['id']?>" data-gps-allowed="<?=$d['status']==='out_for_delivery'?'1':'0'?>"><button type="button" class="button primary small gps-start">Start GPS sharing</button><button type="button" class="button outline small gps-stop" hidden>Stop GPS sharing</button><span class="gps-state">GPS is off. Location is never collected while idle.</span></div></section><?php endforeach;?><?php
}

function op_render_tracking(PDO $pdo,string $token):void
{
    $d=op_tracking_snapshot($pdo,$token);if(!$d){http_response_code(404);echo '<main class="tracking-public"><h1>Tracking link unavailable</h1><p>This link is invalid or has expired.</p></main>';return;}$events=rows($pdo,'SELECT status,note,created_at FROM delivery_events WHERE delivery_id=? ORDER BY created_at,id',[$d['id']]);
    ?><main class="tracking-public"><a class="brand" href="?page=home"><span class="brand-mark">F</span><span>Fresh<span class="brand-light">Stock</span></span></a><section class="panel tracking-card"><div class="eyebrow"><i></i> ORDER TRACKING</div><h1><?=h($d['order_number'])?></h1><p>Tracking ID <?=h($d['tracking_code'])?></p><span class="status-tag <?=h($d['status'])?> tracking-state"><?=h(op_status_label($d['status']))?></span><?php op_render_map($pdo,$d,'public');?><div class="tracking-summary"><div><small>ESTIMATED ARRIVAL</small><b><?=h($d['eta_at']?:'Not available yet')?></b></div><div><small>LAST LOCATION UPDATE</small><b><?=h($d['last_location_at']?:'Waiting for rider GPS')?></b></div><div><small>DELIVERY ADDRESS</small><b><?=h($d['delivery_address']?:'Not recorded')?></b></div><div><small>RIDER</small><b><?=h($d['rider_name']?:'Not assigned')?></b></div><?php if($d['rider_phone']):?><a class="button outline small" href="tel:<?=h($d['rider_phone'])?>">Contact rider</a><?php endif;?></div><h2>Delivery progress</h2><ol class="timeline tracking-timeline"><?php foreach($events as $e):?><li><i></i><div><b><?=h(op_status_label($e['status']))?></b><small><?=h($e['created_at'])?> · <?=h($e['note']?:'')?></small></div></li><?php endforeach;?></ol><p class="microcopy">Arrival time is an estimate and may change. GPS is shown only when the rider has started the active delivery and enabled location.</p></section></main><?php
}

function op_render_dashboard_preview(PDO $pdo,int $owner):void
{
    $active=rows($pdo,"SELECT d.*,o.order_number,o.delivery_address,o.departure_location,c.full_name customer,u.name rider_name FROM deliveries d JOIN orders o ON o.id=d.order_id JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_riders r ON r.id=d.rider_id LEFT JOIN users u ON u.id=r.user_id WHERE d.owner_id=? AND d.status IN ('accepted','preparing','ready_for_pickup','picked_up','out_for_delivery','exception') ORDER BY d.updated_at DESC LIMIT 1",[$owner]);
    ?><section class="dashboard-delivery panel"><div class="panel-heading"><div><h2>Live Tracking Delivery</h2><p>Active delivery · live GPS only</p></div><?php if($active):?><a class="table-action" href="?page=delivery_view&id=<?=(int)$active[0]['id']?>">View details →</a><?php endif;?></div><?php if(!$active):?><div class="empty-live compact-empty"><b>No active deliveries</b><p>Active tracking will appear here after an order is created and a rider starts its delivery.</p><a href="?page=deliveries">Open deliveries →</a></div><?php else:$d=$active[0];?><div class="live-layout"><?php op_render_map($pdo,$d);?><div class="delivery-meta"><b><?=h($d['order_number'])?> · <?=h($d['rider_name']?:'Rider unassigned')?></b><span class="status-tag <?=h($d['status'])?>"><?=h(op_status_label($d['status']))?></span><div class="meta-two"><div><small>DEPARTURE</small><b><?=h($d['departure_location']?:'—')?></b></div><div><small>DESTINATION</small><b><?=h($d['delivery_address']?:'—')?></b></div><div><small>ETA</small><b><?=h($d['eta_at']?:'Unavailable')?></b></div><div><small>LAST GPS</small><b><?=h($d['last_location_at']?:'Waiting for update')?></b></div></div><a class="button outline small" href="?page=delivery_view&id=<?=(int)$d['id']?>">View Details →</a></div></div><?php endif;?></section><?php
}

function op_render_page(PDO $pdo,string $page):bool
{
    $role=$_SESSION['role']??'admin';if($role==='rider'){op_render_rider_dashboard($pdo);return true;}if($role!=='admin')return false;$owner=user_id();
    if($page==='orders'){op_render_orders($pdo,$owner);return true;}if($page==='order_view'){op_render_order_view($pdo,$owner,(int)($_GET['id']??0));return true;}if($page==='customers'){op_render_customers($pdo,$owner);return true;}if($page==='customer_view'){op_render_customer_view($pdo,$owner,(int)($_GET['id']??0));return true;}if($page==='deliveries'){op_render_deliveries($pdo,$owner);return true;}if($page==='delivery_view'){op_render_delivery_view($pdo,$owner,(int)($_GET['id']??0));return true;}return false;
}
